// === Tab: mySketch.js ===
const palette = []

const tiles = []

function setup() {
	if(windowWidth>windowHeight*3/2){
		createCanvas(windowWidth, windowWidth*2/3);
	}else{
		createCanvas(windowHeight*3/2, windowHeight);
	}

	background(10, 10, 15);

	colorMode(HSB)
	const hue1 = random(360)
	const hue2 = (hue1+120)%360
	palette[0] = color(hue1, 50, 100)
	palette[1] = color(hue2, 70, 60)

	const t = floor(random(3,7))
	const xSeg = 3*t
	const ySeg = 2*t

	for(let i=0;i<ySeg;i++){
		for(let j=0;j<xSeg;j++){
			const x = map(j,0,xSeg,0,width)
			const y = map(i,0,ySeg,0,height)
			const w = width/xSeg
			const h = w
			tiles.push(new Tile(x, y, w, h))
		}
	}
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

	background(10, 10, 15)
	for(let tile of tiles){
		tile.draw()
		if(frameCount%60==0 && random()<0.5){
			tile.changeAngle()
		}
	}



  pop();
}

class Tile{
	constructor(x, y, w, h){
		this.x = x
		this.y = y
		this.w = w
		this.h = h
		this.angle = random([0,PI/2,PI,PI/2*3])
		this.targetAngle = this.angle
	}

	changeAngle(){
		this.targetAngle = random([0,PI/2,PI,PI/2*3])
	}

	draw(){
		this.angle = lerp(this.angle, this.targetAngle, 0.1)

		push()

		beginClip()
		rect(this.x-0.5, this.y-0.5, this.w+1, this.h+1)
		endClip()

		rectMode(CENTER)
		translate(this.x+this.w/2, this.y+this.h/2)

		rotate(this.angle)

		const strokeW = this.w
		strokeWeight(strokeW)
		noFill()

		strokeCap(SQUARE)

		let gradient = drawingContext.createRadialGradient(
			-this.w/2, -this.h/2, this.w/2-strokeW/2,
			-this.w/2, -this.h/2, this.w/2+strokeW/2
		)
		gradient.addColorStop(0,color(palette[0]))
		gradient.addColorStop(0.5,color(palette[1]))
		gradient.addColorStop(1,color(palette[0]))
		drawingContext.strokeStyle = gradient
		ellipse(-this.w/2, -this.h/2, this.w, this.h)

		gradient = drawingContext.createRadialGradient(
			this.w/2, this.h/2, this.w/2-strokeW/2,
			this.w/2, this.h/2, this.w/2+strokeW/2
		)
		gradient.addColorStop(0,color(palette[0]))
		gradient.addColorStop(0.5,color(palette[1]))
		gradient.addColorStop(1,color(palette[0]))
		drawingContext.strokeStyle = gradient
		ellipse(this.w/2, this.h/2, this.w, this.h)

		pop()
	}
}

